/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.util.Map;
import java.util.Optional;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import net.civeira.phylax.feature.observe.store.ObsLog;

/**
 * Which stored logs are errors for the issues: level ERROR or FATAL with an exception. The
 * exception comes from the stack of the own logs, the OpenTelemetry attributes
 * ({@code exception.type}, {@code exception.message}, {@code exception.stacktrace}) or the
 * {@code log.args} of the Angular SDK ({@code [{name, message, stack}]}). The logs of the
 * observability itself are left out, so a failure of the grouping never feeds itself.
 */
public final class ErrorEvents {

  private static final ObjectMapper MAPPER = new ObjectMapper();

  private ErrorEvents() {}

  public static Optional<ErrorEvent> from(final ObsLog log, final String ownPackage) {
    if (!"ERROR".equals(log.level()) && !"FATAL".equals(log.level())) {
      return Optional.empty();
    }
    if (null != log.logger() && log.logger().startsWith(ownPackage)) {
      return Optional.empty();
    }
    Map<String, Object> attrs = null == log.attrs() ? Map.of() : log.attrs();
    String type = text(attrs.get("exception.type"));
    String message = text(attrs.get("exception.message"));
    String stack = log.error();
    JsonNode args = args(attrs.get("log.args"));
    if (null != args) {
      type = firstNonNull(type, args.path("name").asText(null));
      message = firstNonNull(message, args.path("message").asText(null));
      stack = firstNonNull(stack, args.path("stack").asText(null));
    }
    if (null == type && null == stack) {
      return Optional.empty();
    }
    if (null == message && null != stack) {
      String first = stack.split("\\R", 2)[0];
      int colon = first.indexOf(':');
      message = colon > 0 ? first.substring(colon + 1).trim() : null;
    }
    return Optional.of(new ErrorEvent(log.src(), log.ts(), log.level(), type,
        firstNonNull(message, log.msg()), stack, log.traceId(), text(attrs.get("fingerprint")),
        log.release(), EventContext.of(attrs)));
  }

  /** The first argument of the SDK log that looks like an error. */
  private static JsonNode args(final Object value) {
    String json = text(value);
    if (null == json) {
      return null;
    }
    try {
      JsonNode node = MAPPER.readTree(json);
      Iterable<JsonNode> items = node.isArray() ? node : java.util.List.of(node);
      for (JsonNode item : items) {
        if (item.isObject() && (item.hasNonNull("stack") || item.hasNonNull("name"))) {
          return item;
        }
      }
    } catch (Exception ex) {
      // Not JSON: no exception in the arguments
    }
    return null;
  }

  private static String text(final Object value) {
    if (null == value) {
      return null;
    }
    String text = String.valueOf(value).trim();
    return text.isEmpty() ? null : text;
  }

  private static String firstNonNull(final String value, final String fallback) {
    return null != value && !value.isBlank() ? value : fallback;
  }
}
